// tokenSpanCss.ts
import { DEFAULT_LIGHT_TOKENS, DEFAULT_DARK_TOKENS } from '@/shared/lib/tokens';

const CELL_TOKEN_MAP = {
  '--cell-token-status-unknown': '--color-error',
  // ... 13 color tokens only
};

function buildVariables() {
  // ONLY injects color tokens (--cell-token-*). No --space-0-5, --shadow-sm, etc.
  const lightDecls = Object.entries(CELL_TOKEN_MAP).map(([k, v]) => `  ${k}: ${DEFAULT_LIGHT_TOKENS[v]};`).join('\n');
  return `:root { ${lightDecls} } ...`;
}
// buildTokenSpanCss() uses var(--space-0-5) in status bar box-shadow → undefined on host → box-shadow dropped → status bar invisible

