// tokens.ts — export STATIC_TOKENS (SSOT, already computed, just not exported)
export const STATIC_TOKENS: TokenRecord = flattenStaticTokens();

// tokenSpanCss.ts
import { DEFAULT_LIGHT_TOKENS, DEFAULT_DARK_TOKENS, STATIC_TOKENS } from '@/shared/lib/tokens';

const STATIC_TOKENS_NEEDED = ['--space-0-5', '--shadow-sm', '--border-width-hairline', '--radius-xs', '--duration-100'];

function buildVariables() {
  const lightDecls = ...; // color tokens (theme-scoped)
  const staticDecls = STATIC_TOKENS_NEEDED.map(n => `  ${n}: ${STATIC_TOKENS[n]};`).join('\n'); // static (theme-independent)
  return `:root { ${lightDecls}\n${staticDecls} }\n[data-theme="dark"] { ${darkDecls}\n${staticDecls} } ...`;
}
// Now var(--space-0-5) resolves to '2px' on host → box-shadow valid → status bar visible

